//! Port of `packages/tui/src/utils.ts` @ pi 0.82.1 (2efa728).
//!
//! Terminal text utilities: visible width (Unicode EAW + ANSI aware), wrapping
//! with ANSI/OSC-8 preservation, truncation, column slicing and overlay segment
//! extraction. All width arithmetic is in terminal columns (`usize`).
//!
//! Intentional differences:
//! - Unicode primitives. Upstream regexes (`\p{Default_Ignorable_Code_Point}`,
//!   `\p{Control}`, `\p{Format}`, `\p{Mark}`, `\p{RGI_Emoji}`, `Script_Extensions`)
//!   run on the runtime's ICU (Node 24 / ICU 76). ICU 76 deviates from the raw
//!   Unicode 16.0.0 UCD files (broader script ranges covering unassigned gaps,
//!   a few post-16.0 marks/emoji), so the generated tables at the bottom of
//!   this file are produced from probes of the actual runtime behavior (the
//!   emoji sequence data is verified byte-identical to the Unicode 16.0
//!   emoji-sequences.txt / emoji-zwj-sequences.txt contents). Generation
//!   scripts are checked in under `scripts/` (`gen-tui-unicode-data.py` +
//!   `icu-probe*.mjs`; see the `@generated` marker at the bottom of this
//!   file). `eastAsianWidth()`
//!   comes from the vendored npm package `get-east-asian-width` v1.6.0 (Unicode
//!   17 data); it is implemented on `unicode-width` 0.2.x (also Unicode 17
//!   data) plus a correction set verified empirically over the whole code
//!   space against the pinned npm package (see `east_asian_width`).
//! - `Intl.Segmenter` (grapheme + word granularity) is replaced by
//!   `unicode-segmentation` 1.13.x (UAX #29, Unicode 17.0 data), which was
//!   verified to match ICU 76's extended grapheme clusters on the full
//!   cross-check corpus (including Thai/Lao AM clusters, ZWJ emoji, RI pairs,
//!   lone combining marks and post-16.0 marks); word segmentation
//!   (`get_word_segmenter`) is only used by T12 editor/word-navigation ports.
//! - `normalizeTerminalOutput` / the ANSI strip in `visible_width` copy whole
//!   characters instead of UTF-16 code units; the two are equivalent because
//!   surrogate halves of an astral character always stay adjacent (ANSI/ESC
//!   bytes are ASCII and can never sit between the halves).
//! - The width cache is a `Mutex<HashMap>` + insertion-order queue; the eviction
//!   policy (which entry is dropped at capacity) is unobservable, so upstream's
//!   `Map` first-key eviction is preserved in spirit.
//! - `extract_segments` uses a fresh `AnsiCodeTracker` per call instead of the
//!   upstream module-level pooled instance; semantics are identical (it is
//!   cleared at the start of every call).
//! - `is_whitespace_char` implements the ECMA-262 `\s` set exactly (includes
//!   U+FEFF, excludes U+0085, which differ from Rust's `char::is_whitespace`).

use std::collections::{HashMap, VecDeque};
use std::sync::{Mutex, MutexGuard};

use unicode_segmentation::UnicodeSegmentation;
use unicode_width::UnicodeWidthChar;

/// Shared grapheme segmenter — equivalent of the upstream module-level
/// `Intl.Segmenter(undefined, { granularity: "grapheme" })` instance.
pub struct GraphemeSegmenter;

/// `getGraphemeSegmenter` (utils.ts:10-12).
pub fn get_grapheme_segmenter() -> GraphemeSegmenter {
    GraphemeSegmenter
}

impl GraphemeSegmenter {
    /// Segment into extended grapheme clusters (UAX #29), like
    /// `Intl.Segmenter#segment(text, { granularity: "grapheme" })`.
    pub fn segment<'a>(&self, text: &'a str) -> unicode_segmentation::Graphemes<'a> {
        text.graphemes(true)
    }
}

/// Shared word segmenter — equivalent of the upstream module-level
/// `Intl.Segmenter(undefined, { granularity: "word" })` instance.
/// Only used by T12 editor / word-navigation ports so far.
pub struct WordSegmenter;

/// `getWordSegmenter` (utils.ts:17-19).
pub fn get_word_segmenter() -> WordSegmenter {
    WordSegmenter
}

impl WordSegmenter {
    /// Segment on UAX #29 word boundaries, yielding every substring including
    /// the whitespace/punctuation between words (like `Intl.Segmenter` word
    /// granularity, which also yields non-word segments).
    pub fn segment<'a>(&self, text: &'a str) -> unicode_segmentation::UWordBounds<'a> {
        text.split_word_bounds()
    }
}

/// Check if a grapheme cluster (after segmentation) could possibly be an RGI
/// emoji. This is a fast heuristic to avoid the expensive RGI emoji check.
/// The tested Unicode blocks are deliberately broad to account for future
/// Unicode additions. (utils.ts:27-37; keep the ranges byte-exact — narrowing
/// them would change widths of e.g. U+25FD/U+25FE, which upstream deliberately
/// does not treat as emoji.)
fn could_be_emoji(segment: &str) -> bool {
    let cp = segment.chars().next().map_or(0, |c| c as u32);
    (0x1f000..=0x1fbff).contains(&cp) // Emoji and Pictograph
        || (0x2300..=0x23ff).contains(&cp) // Misc technical
        || (0x2600..=0x27bf).contains(&cp) // Misc symbols, dingbats
        || (0x2b50..=0x2b55).contains(&cp) // Specific stars/circles
        || segment.contains('\u{fe0f}') // Contains VS16 (emoji presentation selector)
        || segment.encode_utf16().count() > 2 // Multi-codepoint sequences (ZWJ, skin tones, etc.)
}

/// `\p{RGI_Emoji}` matching for a whole grapheme cluster (utils.ts:42
/// `rgiEmojiRegex`). Sequences are matched against the generated Unicode 16.0
/// tables: single codepoints with Emoji_Presentation=Yes, Basic_Emoji
/// (base+VS16), keycaps, modifier sequences, flag RI-pairs, tag sequences and
/// ZWJ sequences.
fn is_rgi_emoji(segment: &str) -> bool {
    let cps: Vec<u32> = segment.chars().map(|c| c as u32).collect();
    match cps.as_slice() {
        [cp] => in_ranges(*cp, EMOJI_PRESENTATION_RANGES),
        [base, 0xfe0f] => in_ranges(*base, EMOJI_BASIC_BASES),
        [base, 0x1f3fb..=0x1f3ff] => in_ranges(*base, EMOJI_MODIFIER_BASES),
        [a, b] => RGI_FLAG_PAIRS
            .binary_search_by(|&(x, y)| (x, y).cmp(&(*a, *b)))
            .is_ok(),
        [base, 0xfe0f, 0x20e3] => in_ranges(*base, KEYCAP_BASES),
        _ => {
            contains_sequence(RGI_TAG_SEQUENCES, &cps) || contains_sequence(RGI_ZWJ_SEQUENCES, &cps)
        }
    }
}

fn contains_sequence(list: &[&[u32]], seq: &[u32]) -> bool {
    list.binary_search_by(|candidate| (*candidate).cmp(seq))
        .is_ok()
}

/// Membership test over sorted, merged `(lo, hi)` inclusive ranges.
///
/// `binary_search_by` expects the closure to order the *element* against the
/// target: `Less` when the range lies entirely before `cp`, `Greater` when it
/// lies entirely after.
fn in_ranges(cp: u32, ranges: &[(u32, u32)]) -> bool {
    ranges
        .binary_search_by(|&(lo, hi)| {
            if hi < cp {
                std::cmp::Ordering::Less
            } else if lo > cp {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}

/// Per-character `\p{Default_Ignorable_Code_Point}` (DerivedCoreProperties.txt,
/// Unicode 16.0).
fn is_default_ignorable(c: char) -> bool {
    in_ranges(c as u32, DEFAULT_IGNORABLE_RANGES)
}

/// Per-character `\p{Mark}` (General_Category Mn/Mc/Me, Unicode 16.0).
fn is_mark(c: char) -> bool {
    in_ranges(c as u32, MARK_RANGES)
}

/// Per-character `\p{Format}` (General_Category Cf, Unicode 16.0).
fn is_format(c: char) -> bool {
    in_ranges(c as u32, FORMAT_RANGES)
}

/// Per-character zero-width test matching `zeroWidthRegex` (utils.ts:40):
/// `[\p{Default_Ignorable_Code_Point}\p{Control}\p{Mark}\p{Surrogate}]`
/// (surrogates cannot occur in a Rust `str`).
fn is_zero_width_char(c: char) -> bool {
    c.is_control() || is_default_ignorable(c) || is_mark(c)
}

/// Per-character test matching `leadingNonPrintingRegex` (utils.ts:41):
/// `[\p{Default_Ignorable_Code_Point}\p{Control}\p{Format}\p{Mark}\p{Surrogate}]`.
fn is_leading_non_printing_char(c: char) -> bool {
    c.is_control() || is_default_ignorable(c) || is_format(c) || is_mark(c)
}

/// Strip the leading run of non-printing characters (`leadingNonPrintingRegex`).
fn strip_leading_non_printing(segment: &str) -> &str {
    let mut start = 0;
    for (i, c) in segment.char_indices() {
        if is_leading_non_printing_char(c) {
            start = i + c.len_utf8();
        } else {
            break;
        }
    }
    &segment[start..]
}

/// `eastAsianWidth()` from the vendored `get-east-asian-width` v1.6.0: 2 iff
/// East Asian Width ∈ {W, F}, else 1 (ambiguous treated as narrow).
///
/// Implemented on `unicode-width` 0.2.x. Verified empirically over the whole
/// code space against the pinned npm package; the only divergences are
/// corrected here:
/// - U+17A4: unicode-width (Unicode 17 data) reports wide, npm reports narrow.
/// - zero-width codepoints (combining marks, U+3164, ...) where unicode-width
///   reports 0 but npm reports 1 (or 2 for the few W/F marks handled by
///   `is_npm_wide_zero_width`).
fn east_asian_width(cp: u32) -> usize {
    let Some(c) = char::from_u32(cp) else {
        return 1; // lone surrogates: neutral in npm's tables
    };
    match UnicodeWidthChar::width(c) {
        Some(2) => {
            if cp == 0x17a4 {
                1
            } else {
                2
            }
        }
        // unicode-width reports 0 for zero-width cps; npm reports 1, except
        // for the few W/F marks handled by is_npm_wide_zero_width (2).
        Some(0) | None if is_npm_wide_zero_width(cp) => 2,
        Some(0) | None => 1,
        // Some(1) for narrow chars, plus unicode-width's single width-3 special
        // case (U+17D8, which npm reports as 1; verified empirically).
        _ => 1,
    }
}

/// W/F codepoints that `unicode-width` classifies as zero-width (marks and
/// U+3164 Hangul filler): npm reports 2 for them.
fn is_npm_wide_zero_width(cp: u32) -> bool {
    matches!(
        cp,
        0x302a..=0x302f | 0x3099..=0x309a | 0x3164 | 0x16fe4 | 0x16ff0..=0x16ff1
    )
}

/// Calculate the terminal width of a single grapheme cluster (utils.ts:167-211).
/// Based on code from the string-width library, but includes a possible-emoji
/// check to avoid running the RGI_Emoji check unnecessarily.
fn grapheme_width(segment: &str) -> usize {
    if segment == "\t" {
        return 3;
    }

    // Zero-width clusters (zeroWidthRegex: every char DI/Cc/Mark).
    if segment.chars().all(is_zero_width_char) {
        return 0;
    }

    // Emoji check with pre-filter
    if could_be_emoji(segment) && is_rgi_emoji(segment) {
        return 2;
    }

    // Get base visible codepoint
    let base = strip_leading_non_printing(segment);
    let Some(cp) = base.chars().next() else {
        return 0;
    };

    // Regional indicator symbols (U+1F1E6..U+1F1FF) are often rendered as
    // full-width emoji in terminals, even when isolated during streaming.
    // Keep width conservative (2) to avoid terminal auto-wrap drift artifacts.
    if (0x1f1e6..=0x1f1ff).contains(&(cp as u32)) {
        return 2;
    }

    let mut width = east_asian_width(cp as u32);

    // Trailing halfwidth/fullwidth forms and AM vowels that segment with a base.
    // (`segment.slice(1)` in the upstream iterates the code points after the
    // first UTF-16 unit; for astral-first segments that is a lone surrogate
    // which never contributes, so skipping the first character is equivalent.)
    if segment.encode_utf16().count() > 1 {
        for c in segment.chars().skip(1) {
            let c = c as u32;
            if (0xff00..=0xffef).contains(&c) {
                width += east_asian_width(c);
            } else if c == 0x0e33 || c == 0x0eb3 {
                width += 1;
            }
        }
    }

    width
}

/// `isPrintableAscii` (utils.ts:51-59): all chars in 0x20..=0x7E.
fn is_printable_ascii(str: &str) -> bool {
    str.bytes().all(|b| (0x20..=0x7e).contains(&b))
}

/// `truncateFragmentToWidth` (utils.ts:61-139): truncate a fragment (typically
/// the ellipsis) to a width, keeping ANSI codes and tabs intact.
fn truncate_fragment_to_width(text: &str, max_width: usize) -> (String, usize) {
    if max_width == 0 || text.is_empty() {
        return (String::new(), 0);
    }

    if is_printable_ascii(text) {
        let clipped = &text[..max_width.min(text.len())];
        return (clipped.to_string(), clipped.len());
    }

    let has_ansi = text.contains('\x1b');
    let has_tabs = text.contains('\t');
    if !has_ansi && !has_tabs {
        let mut result = String::new();
        let mut width = 0;
        for segment in text.graphemes(true) {
            let w = grapheme_width(segment);
            if width + w > max_width {
                break;
            }
            result.push_str(segment);
            width += w;
        }
        return (result, width);
    }

    let mut result = String::new();
    let mut width = 0;
    let mut i = 0;
    let mut pending_ansi = String::new();

    while i < text.len() {
        if let Some(ansi) = extract_ansi_code(text, i) {
            pending_ansi.push_str(ansi.code);
            i += ansi.length;
            continue;
        }

        if text.as_bytes()[i] == b'\t' {
            if width + 3 > max_width {
                break;
            }
            if !pending_ansi.is_empty() {
                result.push_str(&pending_ansi);
                pending_ansi.clear();
            }
            result.push('\t');
            width += 3;
            i += 1;
            continue;
        }

        let mut end = i;
        while end < text.len() && text.as_bytes()[end] != b'\t' {
            if extract_ansi_code(text, end).is_some() {
                break;
            }
            end += 1;
        }

        for segment in text[i..end].graphemes(true) {
            let w = grapheme_width(segment);
            if width + w > max_width {
                return (result, width);
            }
            if !pending_ansi.is_empty() {
                result.push_str(&pending_ansi);
                pending_ansi.clear();
            }
            result.push_str(segment);
            width += w;
        }
        i = end;
    }

    (result, width)
}

/// `finalizeTruncatedResult` (utils.ts:141-160): wrap the kept prefix and
/// ellipsis in resets, optionally padding to `max_width`.
fn finalize_truncated_result(
    prefix: &str,
    prefix_width: usize,
    ellipsis: &str,
    ellipsis_width: usize,
    max_width: usize,
    pad: bool,
) -> String {
    let reset = "\x1b[0m";
    let visible_width = prefix_width + ellipsis_width;
    let mut result = String::new();
    result.push_str(prefix);
    result.push_str(reset);
    if !ellipsis.is_empty() {
        result.push_str(ellipsis);
        result.push_str(reset);
    }
    if pad {
        result.push_str(&" ".repeat(max_width.saturating_sub(visible_width)));
    }
    result
}

/// Width cache (utils.ts:45-46): mirrors the upstream `Map<string, number>`
/// cache with insertion-order eviction at capacity. Eviction choice is
/// unobservable; the queue just approximates the upstream first-key delete.
struct WidthCache {
    map: HashMap<String, usize>,
    order: VecDeque<String>,
}

impl WidthCache {
    fn new() -> Self {
        WidthCache {
            map: HashMap::new(),
            order: VecDeque::new(),
        }
    }

    fn get(&self, key: &str) -> Option<usize> {
        self.map.get(key).copied()
    }

    fn insert(&mut self, key: String, value: usize) {
        if self.map.len() >= WIDTH_CACHE_SIZE {
            if let Some(first) = self.order.pop_front() {
                self.map.remove(&first);
            }
        }
        self.map.insert(key.clone(), value);
        self.order.push_back(key);
    }
}

const WIDTH_CACHE_SIZE: usize = 512;
static WIDTH_CACHE: Mutex<Option<WidthCache>> = Mutex::new(None);

fn width_cache() -> MutexGuard<'static, Option<WidthCache>> {
    WIDTH_CACHE
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
}

/// Calculate the visible width of a string in terminal columns (utils.ts:216-271).
pub fn visible_width(str: &str) -> usize {
    if str.is_empty() {
        return 0;
    }

    // Fast path: pure ASCII printable
    if is_printable_ascii(str) {
        return str.len();
    }

    // Check cache
    if let Some(width) = width_cache().as_ref().and_then(|c| c.get(str)) {
        return width;
    }

    // Normalize: tabs to 3 spaces, strip ANSI escape codes
    let mut clean = str.to_string();
    if str.contains('\t') {
        clean = clean.replace('\t', "   ");
    }
    if clean.contains('\x1b') {
        // Strip supported ANSI/OSC/APC escape sequences in one pass.
        // This covers CSI styling/cursor codes, OSC hyperlinks and prompt
        // markers, and APC sequences like CURSOR_MARKER.
        let mut stripped = String::with_capacity(clean.len());
        let mut i = 0;
        while i < clean.len() {
            if let Some(ansi) = extract_ansi_code(&clean, i) {
                i += ansi.length;
                continue;
            }
            let ch = clean[i..].chars().next().unwrap_or('\u{fffd}');
            stripped.push(ch);
            i += ch.len_utf8();
        }
        clean = stripped;
    }

    // Calculate width
    let mut width = 0;
    for segment in clean.graphemes(true) {
        width += grapheme_width(segment);
    }

    // Cache result
    let mut cache = width_cache();
    cache.get_or_insert_with(WidthCache::new);
    if let Some(cache) = cache.as_mut() {
        cache.insert(str.to_string(), width);
    }

    width
}

/// Normalize text for terminal output without changing logical editor content
/// (utils.ts:284-306). Some terminals render precomposed Thai/Lao AM vowels
/// inconsistently during differential repaint. Their compatibility
/// decompositions have the same cell width but avoid stale-cell artifacts in
/// terminal renderers. Visible tabs are expanded to the fixed width used by
/// layout so terminal tab stops cannot wrap a logical line, while tabs inside
/// terminal string sequences stay untouched.
pub fn normalize_terminal_output(str: &str) -> String {
    let mut normalized = str.to_string();
    if normalized.contains('\u{0e33}') || normalized.contains('\u{0eb3}') {
        normalized = normalized
            .replace('\u{0e33}', "\u{0e4d}\u{0e32}")
            .replace('\u{0eb3}', "\u{0ecd}\u{0eb2}");
    }
    if !normalized.contains('\t') {
        return normalized;
    }

    let mut result = String::with_capacity(normalized.len());
    let mut i = 0;
    while i < normalized.len() {
        if let Some(ansi) = extract_ansi_code(&normalized, i) {
            result.push_str(ansi.code);
            i += ansi.length;
            continue;
        }
        if normalized.as_bytes()[i] == b'\t' {
            result.push_str("   ");
            i += 1;
        } else {
            let ch = normalized[i..].chars().next().unwrap_or('\u{fffd}');
            result.push(ch);
            i += ch.len_utf8();
        }
    }
    result
}

/// An ANSI escape sequence found at a position: the sequence itself and its
/// length in bytes (upstream `{ code, length }`, utils.ts:311).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AnsiCode<'a> {
    pub code: &'a str,
    pub length: usize,
}

/// Extract ANSI escape sequences from a string at the given byte position
/// (utils.ts:311-349). `pos` is a byte offset; the caller must only pass
/// positions at character boundaries.
pub fn extract_ansi_code(str: &str, pos: usize) -> Option<AnsiCode<'_>> {
    let bytes = str.as_bytes();
    if pos >= bytes.len() || bytes[pos] != 0x1b {
        return None;
    }

    let next = bytes.get(pos + 1)?;

    // CSI sequence: ESC [ ... m/G/K/H/J
    if *next == b'[' {
        let mut j = pos + 2;
        while j < bytes.len() && !matches!(bytes[j], b'm' | b'G' | b'K' | b'H' | b'J') {
            j += 1;
        }
        if j < bytes.len() {
            return Some(AnsiCode {
                code: &str[pos..=j],
                length: j + 1 - pos,
            });
        }
        return None;
    }

    // OSC sequence: ESC ] ... BEL or ESC ] ... ST (ESC \)
    // Used for hyperlinks (OSC 8), window titles, etc.
    if *next == b']' {
        let mut j = pos + 2;
        while j < bytes.len() {
            if bytes[j] == 0x07 {
                return Some(AnsiCode {
                    code: &str[pos..=j],
                    length: j + 1 - pos,
                });
            }
            if bytes[j] == 0x1b && bytes.get(j + 1) == Some(&b'\\') {
                return Some(AnsiCode {
                    code: &str[pos..=j + 1],
                    length: j + 2 - pos,
                });
            }
            j += 1;
        }
        return None;
    }

    // APC sequence: ESC _ ... BEL or ESC _ ... ST (ESC \)
    // Used for cursor marker and application-specific commands
    if *next == b'_' {
        let mut j = pos + 2;
        while j < bytes.len() {
            if bytes[j] == 0x07 {
                return Some(AnsiCode {
                    code: &str[pos..=j],
                    length: j + 1 - pos,
                });
            }
            if bytes[j] == 0x1b && bytes.get(j + 1) == Some(&b'\\') {
                return Some(AnsiCode {
                    code: &str[pos..=j + 1],
                    length: j + 2 - pos,
                });
            }
            j += 1;
        }
        return None;
    }

    None
}

/// OSC 8 hyperlink terminator (upstream `type Osc8Terminator`, utils.ts:351).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Osc8Terminator {
    Bel,
    St,
}

/// Active OSC 8 hyperlink state (upstream `interface ActiveHyperlink`,
/// utils.ts:353-357).
#[derive(Debug, Clone)]
struct ActiveHyperlink {
    params: String,
    url: String,
    terminator: Osc8Terminator,
}

/// Result of `parse_osc8_hyperlink`: upstream returns `ActiveHyperlink | null |
/// undefined` — `undefined` (not an OSC 8 code) vs `null` (OSC 8 close with an
/// empty URL).
enum HyperlinkParse {
    NotHyperlink,
    Close,
    Open(ActiveHyperlink),
}

/// `parseOsc8Hyperlink` (utils.ts:359-377).
fn parse_osc8_hyperlink(ansi_code: &str) -> HyperlinkParse {
    if !ansi_code.starts_with("\x1b]8;") {
        return HyperlinkParse::NotHyperlink;
    }

    let terminator = if ansi_code.ends_with('\x07') {
        Osc8Terminator::Bel
    } else {
        Osc8Terminator::St
    };
    let term_len = match terminator {
        Osc8Terminator::Bel => 1,
        Osc8Terminator::St => 2,
    };
    if ansi_code.len() < 4 + term_len {
        return HyperlinkParse::NotHyperlink;
    }
    let body = &ansi_code[4..ansi_code.len() - term_len];
    let Some(separator_index) = body.find(';') else {
        return HyperlinkParse::NotHyperlink;
    };

    let params = &body[..separator_index];
    let url = &body[separator_index + 1..];
    if url.is_empty() {
        return HyperlinkParse::Close;
    }
    HyperlinkParse::Open(ActiveHyperlink {
        params: params.to_string(),
        url: url.to_string(),
        terminator,
    })
}

/// `formatOsc8Hyperlink` (utils.ts:379-381).
fn format_osc8_hyperlink(hyperlink: &ActiveHyperlink) -> String {
    match hyperlink.terminator {
        Osc8Terminator::Bel => format!("\x1b]8;{};{}\x07", hyperlink.params, hyperlink.url),
        Osc8Terminator::St => format!("\x1b]8;{};{}\x1b\\", hyperlink.params, hyperlink.url),
    }
}

/// `formatOsc8Close` (utils.ts:383-385).
fn format_osc8_close(terminator: Osc8Terminator) -> String {
    match terminator {
        Osc8Terminator::Bel => "\x1b]8;;\x07".to_string(),
        Osc8Terminator::St => "\x1b]8;;\x1b\\".to_string(),
    }
}

/// Scan for the first `\x1b[` followed by a run of digits/semicolons terminated
/// by `m`, mirroring the unanchored upstream regex `/\x1b\[([\d;]*)m/`; returns
/// the parameter string between `\x1b[` and `m`.
fn extract_sgr_params(ansi_code: &str) -> Option<&str> {
    let bytes = ansi_code.as_bytes();
    let mut pos = 0;
    while pos + 1 < bytes.len() {
        if bytes[pos] == 0x1b && bytes[pos + 1] == b'[' {
            let mut j = pos + 2;
            while j < bytes.len() && (bytes[j].is_ascii_digit() || bytes[j] == b';') {
                j += 1;
            }
            if j < bytes.len() && bytes[j] == b'm' {
                return Some(&ansi_code[pos + 2..j]);
            }
            // the run is digits/semicolons only, so no ESC can hide inside
            pos = j;
        } else {
            pos += 1;
        }
    }
    None
}

/// Track active ANSI SGR codes to preserve styling across line breaks
/// (utils.ts:390-610, class `AnsiCodeTracker`).
#[derive(Default)]
struct AnsiCodeTracker {
    // Track individual attributes separately so we can reset them specifically
    bold: bool,
    dim: bool,
    italic: bool,
    underline: bool,
    blink: bool,
    inverse: bool,
    hidden: bool,
    strikethrough: bool,
    fg_color: Option<String>, // Stores the full code like "31" or "38;5;240"
    bg_color: Option<String>, // Stores the full code like "41" or "48;5;240"
    active_hyperlink: Option<ActiveHyperlink>,
}

impl AnsiCodeTracker {
    /// `process` (utils.ts:404-536).
    fn process(&mut self, ansi_code: &str) {
        // OSC 8 hyperlink: \x1b]8;;<url>\x1b\\ (open) or \x1b]8;;\x1b\\ (close).
        // Preserve the original terminator because some terminals only make
        // BEL-terminated links clickable. OAuth login URLs use BEL, so
        // reopening wrapped lines with ST made only the first physical line
        // clickable in those terminals.
        match parse_osc8_hyperlink(ansi_code) {
            HyperlinkParse::Open(h) => {
                self.active_hyperlink = Some(h);
                return;
            }
            HyperlinkParse::Close => {
                self.active_hyperlink = None;
                return;
            }
            HyperlinkParse::NotHyperlink => {}
        }

        if !ansi_code.ends_with('m') {
            return;
        }

        // Extract the parameters between \x1b[ and m. The upstream regex
        // /\x1b\[([\d;]*)m/ (utils.ts:420) is UNANCHORED: extractAnsiCode can
        // return a CSI code that swallowed everything up to the first
        // m/G/K/H/J (e.g. `\x1b[?25l...\x1b[31m`), and the tracker then picks
        // the first embedded `\x1b[<digits;>m` — the trailing SGR takes effect.
        let Some(params) = extract_sgr_params(ansi_code) else {
            return;
        };

        if params.is_empty() || params == "0" {
            // Full reset
            self.reset();
            return;
        }

        // Parse parameters (can be semicolon-separated)
        let parts: Vec<&str> = params.split(';').collect();
        let mut i = 0;
        while i < parts.len() {
            let code = parts[i].parse::<i32>().unwrap_or(i32::MIN);

            // Handle 256-color and RGB codes which consume multiple parameters
            if code == 38 || code == 48 {
                // 38;5;N (256 color fg) or 38;2;R;G;B (RGB fg)
                // 48;5;N (256 color bg) or 48;2;R;G;B (RGB bg)
                if parts.get(i + 1) == Some(&"5") && parts.get(i + 2).is_some() {
                    // 256 color: 38;5;N or 48;5;N
                    let color_code = format!("{};{};{}", parts[i], parts[i + 1], parts[i + 2]);
                    if code == 38 {
                        self.fg_color = Some(color_code);
                    } else {
                        self.bg_color = Some(color_code);
                    }
                    i += 3;
                    continue;
                } else if parts.get(i + 1) == Some(&"2") && parts.get(i + 4).is_some() {
                    // RGB color: 38;2;R;G;B or 48;2;R;G;B
                    let color_code = format!(
                        "{};{};{};{};{}",
                        parts[i],
                        parts[i + 1],
                        parts[i + 2],
                        parts[i + 3],
                        parts[i + 4]
                    );
                    if code == 38 {
                        self.fg_color = Some(color_code);
                    } else {
                        self.bg_color = Some(color_code);
                    }
                    i += 5;
                    continue;
                }
            }

            // Standard SGR codes
            match code {
                0 => self.reset(),
                1 => self.bold = true,
                2 => self.dim = true,
                3 => self.italic = true,
                4 => self.underline = true,
                5 => self.blink = true,
                7 => self.inverse = true,
                8 => self.hidden = true,
                9 => self.strikethrough = true,
                21 => self.bold = false, // Some terminals
                22 => {
                    self.bold = false;
                    self.dim = false;
                }
                23 => self.italic = false,
                24 => self.underline = false,
                25 => self.blink = false,
                27 => self.inverse = false,
                28 => self.hidden = false,
                29 => self.strikethrough = false,
                39 => self.fg_color = None, // Default fg
                49 => self.bg_color = None, // Default bg
                // Standard foreground colors 30-37, 90-97
                _ if (30..=37).contains(&code) || (90..=97).contains(&code) => {
                    self.fg_color = Some(code.to_string());
                }
                // Standard background colors 40-47, 100-107
                _ if (40..=47).contains(&code) || (100..=107).contains(&code) => {
                    self.bg_color = Some(code.to_string());
                }
                _ => {}
            }
            i += 1;
        }
    }

    /// `reset` (utils.ts:538-550). SGR reset does not affect OSC 8 hyperlink state.
    fn reset(&mut self) {
        self.bold = false;
        self.dim = false;
        self.italic = false;
        self.underline = false;
        self.blink = false;
        self.inverse = false;
        self.hidden = false;
        self.strikethrough = false;
        self.fg_color = None;
        self.bg_color = None;
    }

    /// Clear all state for reuse (`clear`, utils.ts:553-556).
    #[allow(dead_code)]
    fn clear(&mut self) {
        self.reset();
        self.active_hyperlink = None;
    }

    /// `getActiveCodes` (utils.ts:558-576).
    fn get_active_codes(&self) -> String {
        let mut codes: Vec<&str> = Vec::new();
        if self.bold {
            codes.push("1");
        }
        if self.dim {
            codes.push("2");
        }
        if self.italic {
            codes.push("3");
        }
        if self.underline {
            codes.push("4");
        }
        if self.blink {
            codes.push("5");
        }
        if self.inverse {
            codes.push("7");
        }
        if self.hidden {
            codes.push("8");
        }
        if self.strikethrough {
            codes.push("9");
        }
        if let Some(fg_color) = &self.fg_color {
            codes.push(fg_color);
        }
        if let Some(bg_color) = &self.bg_color {
            codes.push(bg_color);
        }

        let mut result = if codes.is_empty() {
            String::new()
        } else {
            format!("\x1b[{}m", codes.join(";"))
        };
        if let Some(hyperlink) = &self.active_hyperlink {
            result.push_str(&format_osc8_hyperlink(hyperlink));
        }
        result
    }

    /// `hasActiveCodes` (utils.ts:578-592). Not called within utils.ts itself;
    /// kept for the T12 component ports (upstream also only defines it).
    #[allow(dead_code)]
    fn has_active_codes(&self) -> bool {
        self.bold
            || self.dim
            || self.italic
            || self.underline
            || self.blink
            || self.inverse
            || self.hidden
            || self.strikethrough
            || self.fg_color.is_some()
            || self.bg_color.is_some()
            || self.active_hyperlink.is_some()
    }

    /// Get reset codes for attributes that need to be turned off at line end
    /// (`getLineEndReset`, utils.ts:600-609). Underline must be closed to
    /// prevent bleeding into padding. Active OSC 8 hyperlinks must be closed
    /// and re-opened on the next line. Returns empty string if no attributes
    /// need closing.
    fn get_line_end_reset(&self) -> String {
        let mut result = String::new();
        if self.underline {
            result.push_str("\x1b[24m"); // Underline off only
        }
        if let Some(hyperlink) = &self.active_hyperlink {
            // Re-opened at line start via getActiveCodes()
            result.push_str(&format_osc8_close(hyperlink.terminator));
        }
        result
    }
}

/// `updateTrackerFromText` (utils.ts:612-623).
fn update_tracker_from_text(text: &str, tracker: &mut AnsiCodeTracker) {
    let mut i = 0;
    while i < text.len() {
        if let Some(ansi_result) = extract_ansi_code(text, i) {
            tracker.process(ansi_result.code);
            i += ansi_result.length;
        } else {
            let ch = text[i..].chars().next().unwrap_or('\u{fffd}');
            i += ch.len_utf8();
        }
    }
}

/// ECMA-262 `\s` (WhiteSpace + LineTerminator + U+FEFF). Differs from Rust's
/// `char::is_whitespace` (White_Space property): JS includes U+FEFF and
/// excludes U+0085.
fn is_js_whitespace(c: char) -> bool {
    matches!(
        c,
        '\u{0009}'..='\u{000d}'
            | '\u{0020}'
            | '\u{00a0}'
            | '\u{1680}'
            | '\u{2000}'..='\u{200a}'
            | '\u{2028}'
            | '\u{2029}'
            | '\u{202f}'
            | '\u{205f}'
            | '\u{3000}'
            | '\u{feff}'
    )
}

/// JS `trimEnd` semantics (ECMA-262 `\s` set).
fn trim_end_js(s: &str) -> &str {
    let mut end = s.len();
    for (i, c) in s.char_indices().rev() {
        if is_js_whitespace(c) {
            end = i;
        } else {
            break;
        }
    }
    &s[..end]
}

/// JS `trim() === ""` — the token consists entirely of `\s` characters
/// (empty strings pass, matching `"".trim() === ""`).
fn is_all_js_whitespace(s: &str) -> bool {
    s.chars().all(is_js_whitespace)
}

/// `flushCurrent` in `splitIntoTokensWithAnsi` (utils.ts:635-641).
fn flush_current(
    current: &mut String,
    current_kind: &mut Option<SegmentKind>,
    tokens: &mut Vec<String>,
) {
    if current.is_empty() {
        return;
    }
    tokens.push(std::mem::take(current));
    *current_kind = None;
}

/// Split text into words while keeping ANSI codes attached
/// (`splitIntoTokensWithAnsi`, utils.ts:628-702).
fn split_into_tokens_with_ansi(text: &str) -> Vec<String> {
    let mut tokens: Vec<String> = Vec::new();
    let mut current = String::new();
    let mut pending_ansi = String::new(); // ANSI codes waiting to be attached to next visible content
    let mut current_kind: Option<SegmentKind> = None;
    let mut i = 0;

    while i < text.len() {
        if let Some(ansi_result) = extract_ansi_code(text, i) {
            // Hold ANSI codes separately - they'll be attached to the next visible char
            pending_ansi.push_str(ansi_result.code);
            i += ansi_result.length;
            continue;
        }

        let mut end = i;
        while end < text.len() && extract_ansi_code(text, end).is_none() {
            end += 1;
        }

        for segment in text[i..end].graphemes(true) {
            let segment_is_space = segment == " ";
            if !segment_is_space && cjk_break_regex(segment) {
                flush_current(&mut current, &mut current_kind, &mut tokens);
                let token = pending_ansi.clone() + segment;
                pending_ansi.clear();
                tokens.push(token);
                continue;
            }

            let segment_kind = if segment_is_space {
                SegmentKind::Space
            } else {
                SegmentKind::Word
            };
            if !current.is_empty() && current_kind != Some(segment_kind) {
                flush_current(&mut current, &mut current_kind, &mut tokens);
            }

            // Attach any pending ANSI codes to this visible character
            if !pending_ansi.is_empty() {
                current.push_str(&pending_ansi);
                pending_ansi.clear();
            }

            current_kind = Some(segment_kind);
            current.push_str(segment);
        }

        i = end;
    }

    // Handle any remaining pending ANSI codes (attach to last token)
    if !pending_ansi.is_empty() {
        if !current.is_empty() {
            current.push_str(&pending_ansi);
        } else if let Some(last) = tokens.last_mut() {
            last.push_str(&pending_ansi);
        } else {
            current = pending_ansi;
        }
    }

    if !current.is_empty() {
        tokens.push(current);
    }

    tokens
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum SegmentKind {
    Space,
    Word,
}

/// Port of the `cjkBreakRegex` constant (utils.ts:48-49):
/// `[\p{Script_Extensions=Han}\p{Script_Extensions=Hiragana}\p{Script_Extensions=Katakana}\p{Script_Extensions=Hangul}\p{Script_Extensions=Bopomofo}]`
/// used as `cjkBreakRegex.test(segment)`: true if the segment contains any
/// character whose Script_Extensions includes one of the five CJK scripts.
pub fn cjk_break_regex(segment: &str) -> bool {
    segment
        .chars()
        .any(|c| in_ranges(c as u32, CJK_BREAK_RANGES))
}

/// Wrap text with ANSI codes preserved (utils.ts:715-738, `wrapTextWithAnsi`).
///
/// ONLY does word wrapping - NO padding, NO background colors.
/// Returns lines where each line is <= width visible chars.
/// Active ANSI codes are preserved across line breaks.
///
/// - `text` - Text to wrap (may contain ANSI codes and newlines)
/// - `width` - Maximum visible width per line
/// - Returns: Array of wrapped lines (NOT padded to width)
pub fn wrap_text_with_ansi(text: &str, width: usize) -> Vec<String> {
    if text.is_empty() {
        return vec![String::new()];
    }

    // Handle newlines by processing each line separately
    // Track ANSI state across lines so styles carry over after literal newlines
    let input_lines = text.replace("\r\n", "\n").replace('\r', "\n");
    let mut result: Vec<String> = Vec::new();
    let mut tracker = AnsiCodeTracker::default();

    for input_line in input_lines.split('\n') {
        // Prepend active ANSI codes from previous lines (except for first line)
        let prefix = if result.is_empty() {
            String::new()
        } else {
            tracker.get_active_codes()
        };
        let wrapped_lines = wrap_single_line(&(prefix + input_line), width);
        result.extend(wrapped_lines);
        // Update tracker with codes from this line for next iteration
        update_tracker_from_text(input_line, &mut tracker);
    }

    if result.is_empty() {
        result.push(String::new());
    }
    result
}

/// `wrapSingleLine` (utils.ts:740-819).
fn wrap_single_line(line: &str, width: usize) -> Vec<String> {
    if line.is_empty() {
        return vec![String::new()];
    }

    let visible_length = visible_width(line);
    if visible_length <= width {
        return vec![line.to_string()];
    }

    let mut wrapped: Vec<String> = Vec::new();
    let mut tracker = AnsiCodeTracker::default();
    let tokens = split_into_tokens_with_ansi(line);

    let mut current_line = String::new();
    let mut current_visible_length = 0usize;

    for token in tokens {
        let token_visible_length = visible_width(&token);
        let is_whitespace = is_all_js_whitespace(&token);

        // Token itself is too long - break it character by character
        if token_visible_length > width && !is_whitespace {
            if !current_line.is_empty() {
                // Add specific reset for underline only (preserves background)
                let line_end_reset = tracker.get_line_end_reset();
                if !line_end_reset.is_empty() {
                    current_line.push_str(&line_end_reset);
                }
                wrapped.push(std::mem::take(&mut current_line));
                // (upstream also assigns currentVisibleLength = 0 here; the
                // value is overwritten below before being read, so it is dropped)
            }

            // Break long token - breakLongWord handles its own resets
            let broken = break_long_word(&token, width, &mut tracker);
            for broken_line in &broken[..broken.len() - 1] {
                wrapped.push(broken_line.clone());
            }
            current_line = broken.last().cloned().unwrap_or_default();
            current_visible_length = visible_width(&current_line);
            continue;
        }

        // Check if adding this token would exceed width
        let total_needed = current_visible_length + token_visible_length;

        if total_needed > width && current_visible_length > 0 {
            // Trim trailing whitespace, then add underline reset (not full
            // reset, to preserve background)
            let mut line_to_wrap = trim_end_js(&current_line).to_string();
            let line_end_reset = tracker.get_line_end_reset();
            if !line_end_reset.is_empty() {
                line_to_wrap.push_str(&line_end_reset);
            }
            wrapped.push(line_to_wrap);
            if is_whitespace {
                // Don't start new line with whitespace
                current_line = tracker.get_active_codes();
                current_visible_length = 0;
            } else {
                current_line = tracker.get_active_codes() + &token;
                current_visible_length = token_visible_length;
            }
        } else {
            // Add to current line
            current_line.push_str(&token);
            current_visible_length += token_visible_length;
        }

        update_tracker_from_text(&token, &mut tracker);
    }

    if !current_line.is_empty() {
        // No reset at end of final line - let caller handle it
        wrapped.push(current_line);
    }

    // Trailing whitespace can cause lines to exceed the requested width
    if wrapped.is_empty() {
        wrapped.push(String::new());
    }
    wrapped
        .into_iter()
        .map(|line| trim_end_js(&line).to_string())
        .collect()
}

/// `PUNCTUATION_REGEX` (utils.ts:821): the punctuation character class
/// `/[(){}[\]<>.,;:'"!?+\-=*/\\|&%^$#@~`]/`.
pub const PUNCTUATION_REGEX: &str = "(){}[]<>.,;:'\"!?+-=*/\\|&%^$#@~`";

/// Check if a character is whitespace (`isWhitespaceChar`, utils.ts:826-828;
/// ECMA-262 `\s`).
pub fn is_whitespace_char(char: &str) -> bool {
    char.chars().any(is_js_whitespace)
}

/// Check if a character is punctuation (`isPunctuationChar`, utils.ts:833-835).
pub fn is_punctuation_char(char: &str) -> bool {
    char.chars().any(|c| PUNCTUATION_REGEX.contains(c))
}

/// `breakLongWord` (utils.ts:837-904): break a long word grapheme by grapheme,
/// keeping ANSI codes attached; handles its own line-end resets.
fn break_long_word(word: &str, width: usize, tracker: &mut AnsiCodeTracker) -> Vec<String> {
    let mut lines: Vec<String> = Vec::new();
    let mut current_line = tracker.get_active_codes();
    let mut current_width = 0usize;

    // First, separate ANSI codes from visible content
    // We need to handle ANSI codes specially since they're not graphemes
    let mut i = 0;
    let mut segments: Vec<WordSegment> = Vec::new();

    while i < word.len() {
        if let Some(ansi_result) = extract_ansi_code(word, i) {
            segments.push(WordSegment::Ansi(ansi_result.code));
            i += ansi_result.length;
        } else {
            // Find the next ANSI code or end of string
            let mut end = i;
            while end < word.len() && extract_ansi_code(word, end).is_none() {
                end += 1;
            }
            // Segment this non-ANSI portion into graphemes
            for seg in word[i..end].graphemes(true) {
                segments.push(WordSegment::Grapheme(seg));
            }
            i = end;
        }
    }

    // Now process segments
    for seg in segments {
        match seg {
            WordSegment::Ansi(value) => {
                current_line.push_str(value);
                tracker.process(value);
                continue;
            }
            WordSegment::Grapheme(grapheme) => {
                let grapheme_width = visible_width(grapheme);

                if current_width + grapheme_width > width {
                    // Add specific reset for underline only (preserves background)
                    let line_end_reset = tracker.get_line_end_reset();
                    if !line_end_reset.is_empty() {
                        current_line.push_str(&line_end_reset);
                    }
                    lines.push(std::mem::take(&mut current_line));
                    current_line = tracker.get_active_codes();
                    current_width = 0;
                }

                current_line.push_str(grapheme);
                current_width += grapheme_width;
            }
        }
    }

    if !current_line.is_empty() {
        // No reset at end of final segment - caller handles continuation
        lines.push(current_line);
    }

    if lines.is_empty() {
        lines.push(String::new());
    }
    lines
}

enum WordSegment<'a> {
    Ansi(&'a str),
    Grapheme(&'a str),
}

/// Apply background color to a line, padding to full width (utils.ts:914-923,
/// `applyBackgroundToLine`).
///
/// - `line` - Line of text (may contain ANSI codes)
/// - `width` - Total width to pad to
/// - `bg_fn` - Background color function
/// - Returns: Line with background applied and padded to width
pub fn apply_background_to_line<F>(line: &str, width: usize, bg_fn: F) -> String
where
    F: Fn(&str) -> String,
{
    // Calculate padding needed
    let visible_len = visible_width(line);
    let padding_needed = width.saturating_sub(visible_len);
    let padding = " ".repeat(padding_needed);

    // Apply background to content + padding
    let with_padding = format!("{line}{padding}");
    bg_fn(&with_padding)
}

/// Truncate text to fit within a maximum visible width, adding ellipsis if
/// needed; optionally pad with spaces to reach exactly maxWidth. Properly
/// handles ANSI escape codes (they don't count toward width).
/// (utils.ts:936-1072, `truncateToWidth`)
///
/// - `text` - Text to truncate (may contain ANSI codes)
/// - `max_width` - Maximum visible width
/// - `ellipsis` - Ellipsis string to append when truncating (default: "...")
/// - `pad` - If true, pad result with spaces to exactly maxWidth (default: false)
/// - Returns: Truncated text, optionally padded to exactly maxWidth
pub fn truncate_to_width(text: &str, max_width: usize, ellipsis: &str, pad: bool) -> String {
    if max_width == 0 {
        return String::new();
    }

    if text.is_empty() {
        return if pad {
            " ".repeat(max_width)
        } else {
            String::new()
        };
    }

    let ellipsis_width = visible_width(ellipsis);
    if ellipsis_width >= max_width {
        let text_width = visible_width(text);
        if text_width <= max_width {
            return if pad {
                text.to_string() + &" ".repeat(max_width - text_width)
            } else {
                text.to_string()
            };
        }

        let clipped_ellipsis = truncate_fragment_to_width(ellipsis, max_width);
        if clipped_ellipsis.1 == 0 {
            return if pad {
                " ".repeat(max_width)
            } else {
                String::new()
            };
        }
        return finalize_truncated_result(
            "",
            0,
            &clipped_ellipsis.0,
            clipped_ellipsis.1,
            max_width,
            pad,
        );
    }

    if is_printable_ascii(text) {
        if text.len() <= max_width {
            return if pad {
                text.to_string() + &" ".repeat(max_width - text.len())
            } else {
                text.to_string()
            };
        }
        let target_width = max_width - ellipsis_width;
        return finalize_truncated_result(
            &text[..target_width],
            target_width,
            ellipsis,
            ellipsis_width,
            max_width,
            pad,
        );
    }

    let target_width = max_width - ellipsis_width;
    let mut result = String::new();
    let mut pending_ansi = String::new();
    let mut visible_so_far = 0usize;
    let mut kept_width = 0usize;
    let mut keep_contiguous_prefix = true;
    let mut overflowed = false;
    // Assigned in both branches below (never read from the initializer).
    let exhausted_input;
    let has_ansi = text.contains('\x1b');
    let has_tabs = text.contains('\t');

    if !has_ansi && !has_tabs {
        for segment in text.graphemes(true) {
            let width = grapheme_width(segment);
            if keep_contiguous_prefix && kept_width + width <= target_width {
                result.push_str(segment);
                kept_width += width;
            } else {
                keep_contiguous_prefix = false;
            }
            visible_so_far += width;
            if visible_so_far > max_width {
                overflowed = true;
                break;
            }
        }
        exhausted_input = !overflowed;
    } else {
        let mut i = 0;
        while i < text.len() {
            if let Some(ansi) = extract_ansi_code(text, i) {
                pending_ansi.push_str(ansi.code);
                i += ansi.length;
                continue;
            }

            if text.as_bytes()[i] == b'\t' {
                if keep_contiguous_prefix && kept_width + 3 <= target_width {
                    if !pending_ansi.is_empty() {
                        result.push_str(&pending_ansi);
                        pending_ansi.clear();
                    }
                    result.push('\t');
                    kept_width += 3;
                } else {
                    keep_contiguous_prefix = false;
                    pending_ansi.clear();
                }
                visible_so_far += 3;
                if visible_so_far > max_width {
                    overflowed = true;
                    break;
                }
                i += 1;
                continue;
            }

            let mut end = i;
            while end < text.len() && text.as_bytes()[end] != b'\t' {
                if extract_ansi_code(text, end).is_some() {
                    break;
                }
                end += 1;
            }

            for segment in text[i..end].graphemes(true) {
                let width = grapheme_width(segment);
                if keep_contiguous_prefix && kept_width + width <= target_width {
                    if !pending_ansi.is_empty() {
                        result.push_str(&pending_ansi);
                        pending_ansi.clear();
                    }
                    result.push_str(segment);
                    kept_width += width;
                } else {
                    keep_contiguous_prefix = false;
                    pending_ansi.clear();
                }

                visible_so_far += width;
                if visible_so_far > max_width {
                    overflowed = true;
                    break;
                }
            }
            if overflowed {
                break;
            }
            i = end;
        }
        exhausted_input = i >= text.len();
    }

    if !overflowed && exhausted_input {
        return if pad {
            text.to_string() + &" ".repeat(max_width.saturating_sub(visible_so_far))
        } else {
            text.to_string()
        };
    }

    finalize_truncated_result(
        &result,
        kept_width,
        ellipsis,
        ellipsis_width,
        max_width,
        pad,
    )
}

/// Extract a range of visible columns from a line. Handles ANSI codes and wide
/// chars (utils.ts:1078-1080, `sliceByColumn`).
/// - `strict` - If true, exclude wide chars at boundary that would extend past the range
pub fn slice_by_column(line: &str, start_col: usize, length: usize, strict: bool) -> String {
    slice_with_width(line, start_col, length, strict).0
}

/// Like sliceByColumn but also returns the actual visible width of the result
/// (utils.ts:1083-1128, `sliceWithWidth`).
pub fn slice_with_width(
    line: &str,
    start_col: usize,
    length: usize,
    strict: bool,
) -> (String, usize) {
    if length == 0 {
        return (String::new(), 0);
    }
    let end_col = start_col + length;
    let mut result = String::new();
    let mut result_width = 0usize;
    let mut current_col = 0usize;
    let mut i = 0;
    let mut pending_ansi = String::new();

    while i < line.len() {
        if let Some(ansi) = extract_ansi_code(line, i) {
            if current_col >= start_col && current_col < end_col {
                result.push_str(ansi.code);
            } else if current_col < start_col {
                pending_ansi.push_str(ansi.code);
            }
            i += ansi.length;
            continue;
        }

        let mut text_end = i;
        while text_end < line.len() && extract_ansi_code(line, text_end).is_none() {
            text_end += 1;
        }

        for segment in line[i..text_end].graphemes(true) {
            let w = grapheme_width(segment);
            let in_range = current_col >= start_col && current_col < end_col;
            let fits = !strict || current_col + w <= end_col;
            if in_range && fits {
                if !pending_ansi.is_empty() {
                    result.push_str(&pending_ansi);
                    pending_ansi.clear();
                }
                result.push_str(segment);
                result_width += w;
            }
            current_col += w;
            if current_col >= end_col {
                break;
            }
        }
        i = text_end;
        if current_col >= end_col {
            break;
        }
    }
    (result, result_width)
}

/// "before" and "after" segments of a line (`extractSegments`, utils.ts:1138-1209).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Segments {
    pub before: String,
    pub before_width: usize,
    pub after: String,
    pub after_width: usize,
}

/// Extract "before" and "after" segments from a line in a single pass
/// (utils.ts:1138-1209, `extractSegments`).
/// Used for overlay compositing where we need content before and after the
/// overlay region. Preserves styling from before the overlay that should
/// affect content after it.
pub fn extract_segments(
    line: &str,
    before_end: usize,
    after_start: usize,
    after_len: usize,
    strict_after: bool,
) -> Segments {
    let mut before = String::new();
    let mut before_width = 0usize;
    let mut after = String::new();
    let mut after_width = 0usize;
    let mut current_col = 0usize;
    let mut i = 0;
    let mut pending_ansi_before = String::new();
    let mut after_started = false;
    let after_end = after_start + after_len;

    // Track styling state so "after" inherits styling from before the overlay.
    // (Upstream pools a module-level tracker; a fresh one is equivalent.)
    let mut style_tracker = AnsiCodeTracker::default();

    while i < line.len() {
        if let Some(ansi) = extract_ansi_code(line, i) {
            // Track all SGR codes to know styling state at afterStart
            style_tracker.process(ansi.code);
            // Include ANSI codes in their respective segments
            if current_col < before_end {
                pending_ansi_before.push_str(ansi.code);
            } else if current_col >= after_start && current_col < after_end && after_started {
                // Only include after we've started "after" (styling already prepended)
                after.push_str(ansi.code);
            }
            i += ansi.length;
            continue;
        }

        let mut text_end = i;
        while text_end < line.len() && extract_ansi_code(line, text_end).is_none() {
            text_end += 1;
        }

        for segment in line[i..text_end].graphemes(true) {
            let w = grapheme_width(segment);

            if current_col < before_end && current_col + w <= before_end {
                if !pending_ansi_before.is_empty() {
                    before.push_str(&pending_ansi_before);
                    pending_ansi_before.clear();
                }
                before.push_str(segment);
                before_width += w;
            } else if current_col >= after_start && current_col < after_end {
                let fits = !strict_after || current_col + w <= after_end;
                if fits {
                    // On first "after" grapheme, prepend inherited styling from before overlay
                    if !after_started {
                        after.push_str(&style_tracker.get_active_codes());
                        after_started = true;
                    }
                    after.push_str(segment);
                    after_width += w;
                }
            }

            current_col += w;
            // Early exit: done with "before" only, or done with both segments
            let done_at = if after_len == 0 {
                before_end
            } else {
                after_end
            };
            if current_col >= done_at {
                break;
            }
        }
        i = text_end;
        let done_at = if after_len == 0 {
            before_end
        } else {
            after_end
        };
        if current_col >= done_at {
            break;
        }
    }

    Segments {
        before,
        before_width,
        after,
        after_width,
    }
}

